function showBanScreen(reason,bannedBy){if(document.getElementById('banOverlay'))return;var o=document.createElement('div');o.id='banOverlay';o.style.cssText='position:fixed;top:0;left:0;width:100vw;height:100vh;background:radial-gradient(circle at 50% 30%,#3a0000 0%,#0d0d0d 70%);color:#fff;z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:20px;text-align:center';o.innerHTML='<div><div style="font-size:6rem">🚫</div><h1 style="font-family:Georgia,serif;color:#ff4d4d;border:none">Account Banned</h1><p>Reason: '+escapeHtml(reason||'Violation')+'</p><p>Banned by: '+escapeHtml(bannedBy||'Staff')+'</p></div>';document.body.appendChild(o);document.body.style.overflow='hidden';}
function showKickScreen(kickUntil,reason,kickedBy){if(document.getElementById('kickOverlay'))return;function fmt(){var ms=kickUntil-Date.now();if(ms<=0)return '0s';return formatDurationShort(ms);}var o=document.createElement('div');o.id='kickOverlay';o.style.cssText='position:fixed;top:0;left:0;width:100vw;height:100vh;background:radial-gradient(circle at 50% 30%,#3a2500 0%,#0d0d0d 70%);color:#fff;z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:20px;text-align:center';o.innerHTML='<div><div style="font-size:6rem">⏸️</div><h1 style="font-family:Georgia,serif;color:#ffaa00;border:none">Suspended</h1><p>Reason: '+escapeHtml(reason||'Violation')+'</p><p>By: '+escapeHtml(kickedBy||'Staff')+'</p><p style="font-family:monospace;color:#ffaa00;font-size:1.3rem" id="kickCountdown">'+fmt()+'</p></div>';document.body.appendChild(o);document.body.style.overflow='hidden';if(_kickInterval)clearInterval(_kickInterval);_kickInterval=setInterval(function(){var el=document.getElementById('kickCountdown');if(!el){clearInterval(_kickInterval);_kickInterval=null;return;}el.textContent=fmt();if(kickUntil-Date.now()<=0){clearInterval(_kickInterval);_kickInterval=null;document.body.style.overflow='';o.remove();window.location.reload();}},1000);}
async function enforceBanKick(){if(!currentUser)return false;if(document.getElementById('banOverlay')||document.getElementById('kickOverlay'))return true;if(currentUser.isBanned){showBanScreen(currentUser.banReason,currentUser.bannedBy);return true;}if(currentUser.kickUntil&&currentUser.kickUntil>Date.now()){showKickScreen(currentUser.kickUntil,currentUser.kickReason,currentUser.kickedBy);return true;}try{var r=await fetch(FIREBASE_BASE_URL+'/users/'+currentUser.rblxUserId+'.json');if(r.ok){var u=await r.json();if(u){if(u.isBanned){showBanScreen(u.banReason,u.bannedBy);return true;}if(u.kickUntil&&u.kickUntil>Date.now()){showKickScreen(u.kickUntil,u.kickReason,u.kickedBy);return true;}var savedCart=currentUser.shopCart;Object.keys(u).forEach(function(k){if(u[k]!==undefined&&_CLIENT_OWNED_FIELDS.indexOf(k)===-1)currentUser[k]=u[k];});currentUser.shopCart=savedCart||currentUser.shopCart||[];localStorage.setItem('app_current_user',JSON.stringify(currentUser));}}}catch(e){}return false;}
