async function purchasePass(pt){if(!currentUser)return;if(pt==='VIP'&&currentUser.isVIP){showToast("Already bought!","error");return;}if(pt==='Premium'&&currentUser.isPremium){showToast("Already bought!","error");return;}var cost=pt==='VIP'?12500:25000;if(!isOwnerAccount(currentUser)&&(currentUser.points||0)<cost){showToast("❌ Need "+cost.toLocaleString()+" Coins!","error");return;}if(!confirm("Buy "+pt+" for "+cost.toLocaleString()+" Coins?"))return;if(!isOwnerAccount(currentUser))currentUser.points-=cost;if(pt==='VIP'){currentUser.isVIP=true;currentUser.points+=250;showToast('🎉 VIP!','success');}else{currentUser.isPremium=true;currentUser.isVIP=true;currentUser.points+=1500;currentUser.premiumFreeClaims=(currentUser.premiumFreeClaims||0)+2;showToast('🎉 Premium!','success');}saveUserData();updateUserStatusHeader();openBuyPasses();}
