async function castVote(pid,oi){if(!currentUser)return;var now=Date.now();var lvt=currentUser.lastVoteTime||0;if(now-lvt<3600000){showToast("⏳ Cooldown!","error");return;}var poll=null;for(var i=0;i<globalPolls.length;i++){if(globalPolls[i].id===pid){poll=globalPolls[i];break;}}if(!poll||!poll.options[oi])return;poll.options[oi].votes=(poll.options[oi].votes||0)+1;try{await fetch(FIREBASE_BASE_URL+'/polls/'+pid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(poll)});}catch(e){}currentUser.lastVoteTime=now;currentUser.points=(currentUser.points||0)+5;saveUserData();updateUserStatusHeader();showToast("✅ +5 Coins!","success");renderQuestsPage();}
