  h+='<div class="logistics-opt '+(checkoutState.payment==='Maya'?'active':'')+'" onclick="setCheckoutPayment(\'Maya\')">'+LOGOS.Maya+'<span style="font-size:.78rem;font-weight:bold">Maya</span><span style="font-size:.65rem;color:#28a745">⚙️ Auto-pay</span></div>';
