async function submitXdrgOrder(){
  if(!currentUser)return;
  var cart=currentUser.shopCart||[];
  if(cart.length===0){showToast("❌ Cart empty","error");return;}
  var name=(currentUser.name||currentUser.displayName||'').trim();
  var num=(currentUser.number||'').trim();
  var addr=((document.getElementById('chkAddress')||{}).value||'').trim();
  var postal=((document.getElementById('chkPostal')||{}).value||'').trim();
  if(!name||!num){showToast("❌ Missing profile Name/Number","error");return;}
  if(!addr){showToast("❌ Fill in Address","error");return;}
  if(!postal){showToast("❌ Fill in Postal Code","error");return;}
  if(checkoutState.paylater&&checkoutState.paylaterTerm===0){showToast("❌ Choose PayLater term","error");return;}
  var totalM=0,totalC=0;cart.forEach(function(it){totalM+=(it.priceMoney||0);totalC+=(it.priceCoins||0);});
  if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya'){
    if(!isOwnerAccount(currentUser)){
      if((currentUser.points||0)<totalC){showToast("❌ Not enough coins: need "+totalC.toLocaleString(),"error");return;}
      currentUser.points-=totalC;
    }
  }
  var orderId="XDRG-ORD-"+Date.now().toString().slice(-8);
  var payStatus=(checkoutState.payment==='GCash'||checkoutState.payment==='Maya')?'Paid-Online':'Pending-COD';
  var order={id:orderId,userId:String(currentUser.rblxUserId),userName:currentUser.username||currentUser.name,items:cart,totalMoney:totalM,totalCoins:totalC,shipping:{name:name,number:num,address:addr,postal:postal},barrow:checkoutState.barrow,paylater:checkoutState.paylater,paylaterTerm:checkoutState.paylaterTerm,paylaterMonthly:checkoutState.paylaterTerm>0?(totalM/checkoutState.paylaterTerm).toFixed(2):0,logistics:checkoutState.logistics||'J&T',payment:checkoutState.payment,paymentStatus:payStatus,status:'Pending',orderIdText:'',addressProcess:'',timestamp:Date.now()};
  currentUser.shopCart=[];saveUserData();updateUserStatusHeader();
  var orders=getAllShopOrders();orders.push(order);saveAllShopOrders(orders);
  try{
    await fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+orderId+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(order)});
    var nid="SHOP-ORDER-"+Date.now();
    var payMsg=checkoutState.payment==='COD'?('🚚 COD ₱'+totalM.toLocaleString()):('✅ Paid ₱'+totalM.toLocaleString()+' via '+checkoutState.payment);
    await fetch(FIREBASE_BASE_URL+'/owner_alerts/'+nid+'.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:nid,title:'🛒 New Order — '+checkoutState.payment,message:name+' (@'+currentUser.username+') placed '+orderId+'\n'+payMsg+'\nShip: '+addr+', '+postal+'\nNumber: '+num,timestamp:Date.now(),isShopOrder:true,orderId:orderId})});
  }catch(e){}
  showToast('✅ Order placed! '+orderId,'success');
  if(checkoutState.payment==='GCash'||checkoutState.payment==='Maya')setTimeout(function(){showToast('💸 Auto-paid ₱'+totalM.toLocaleString(),'success');},1600);
  else setTimeout(function(){showToast('🚚 Pay ₱'+totalM.toLocaleString()+' on delivery','info');},1600);
  if(typeof triggerConfetti==='function')setTimeout(triggerConfetti,400);
  checkoutState={paylater:false,paylaterTerm:0,logistics:'J&T',payment:'COD',barrow:false};
  setShopTab('orders');
}
function renderShopOrders(){var myOrders=getAllShopOrders().filter(function(o){return String(o.userId)===String(currentUser.rblxUserId);});if(myOrders.length===0)return '<div class="empty-state"><div class="icon">📋</div><p>No orders yet.</p><button class="btn-save" style="margin-top:12px;background:#8b5cf6" onclick="setShopTab(\'products\')">← Go Shopping</button></div>';var h='';myOrders.slice().reverse().forEach(function(o){var items=o.items.map(function(it){return escapeHtml(it.name);}).join(', ');var stClass=o.status==='Pending'?'status-pending':(o.status==='Cancelled'?'status-unsuccessful':'status-successful');h+='<div class="order-card"><div class="oc-header"><div class="oc-id">'+escapeHtml(o.orderIdText||o.id)+'</div><span class="status-badge '+stClass+'">'+escapeHtml(o.status)+'</span></div><div class="oc-info"><div><b>Items:</b> '+items+'</div><div><b>Total:</b> ₱'+(o.totalMoney||0).toLocaleString()+(o.totalCoins?' / 🪙 '+o.totalCoins.toLocaleString():'')+'</div><div><b>Ship:</b> '+escapeHtml(o.shipping.name)+', '+escapeHtml(o.shipping.number)+'</div><div><b>Address:</b> '+escapeHtml(o.shipping.address)+', '+escapeHtml(o.shipping.postal)+'</div><div><b>Logistics:</b> '+escapeHtml(o.logistics)+'</div><div><b>Payment:</b> '+escapeHtml(o.payment)+(o.paylater?' (PayLater '+o.paylaterTerm+'mo)':'')+(o.barrow?' + Barrow':'')+'</div>'+(o.paymentStatus?'<div><b>Pay Status:</b> '+escapeHtml(o.paymentStatus)+'</div>':'')+(o.orderIdText?'<div><b>Owner ID:</b> '+escapeHtml(o.orderIdText)+'</div>':'')+(o.addressProcess?'<div><b>Address Process:</b> '+escapeHtml(o.addressProcess)+'</div>':'')+'<div><b>Placed:</b> '+new Date(o.timestamp).toLocaleString()+'</div></div>'+(o.status==='Pending'?'<button class="btn-danger" style="width:100%;margin-top:10px" onclick="cancelXdrgOrder(\''+o.id+'\')">❌ Cancel</button>':'')+'</div>';});return h;}
function addToCart(pid){if(!currentUser){showToast("❌ Login required","error");return;}var products=getAllShopProducts();var p=null;for(var i=0;i<products.length;i++){if(products[i].id===pid){p=products[i];break;}}if(!p){showToast("❌ Product not found","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];for(var j=0;j<currentUser.shopCart.length;j++){if(currentUser.shopCart[j].id===pid){showToast("Already in cart","info");return;}}currentUser.shopCart.push({id:p.id,name:p.name,priceMoney:p.priceMoney||0,priceCoins:p.priceCoins||0,image:p.image||'',category:p.category||'',qty:1});saveUserData();renderXdrgShop();showToast('✅ Added!','success');}
function buyNow(pid){if(!currentUser){showToast("❌ Login required","error");return;}var products=getAllShopProducts();var p=null;for(var i=0;i<products.length;i++){if(products[i].id===pid){p=products[i];break;}}if(!p){showToast("❌ Not found","error");return;}if(!currentUser.shopCart)currentUser.shopCart=[];var exists=false;for(var j=0;j<currentUser.shopCart.length;j++){if(currentUser.shopCart[j].id===pid){exists=true;break;}}if(!exists){currentUser.shopCart.push({id:p.id,name:p.name,priceMoney:p.priceMoney||0,priceCoins:p.priceCoins||0,image:p.image||'',category:p.category||'',qty:1});saveUserData();}checkoutState={paylater:false,paylaterTerm:0,logistics:'J&T',payment:'COD',barrow:false};shopTab='checkout';renderXdrgShop();showToast('⚡ Ready to checkout','success');}
function removeFromCart(pid){if(!currentUser)return;currentUser.shopCart=(currentUser.shopCart||[]).filter(function(x){return x.id!==pid;});saveUserData();renderXdrgShop();showToast('Removed','info');}
function togglePayLater(on){checkoutState.paylater=on;if(!on)checkoutState.paylaterTerm=0;renderXdrgShop();}
function setPayLaterTerm(t){checkoutState.paylaterTerm=t;renderXdrgShop();}
function setCheckoutLogistics(l){checkoutState.logistics=l;renderXdrgShop();}
function setCheckoutPayment(p){checkoutState.payment=p;renderXdrgShop();}
function cancelXdrgOrder(oid){if(!currentUser)return;if(!confirm("Cancel?"))return;var orders=getAllShopOrders();var idx=-1;for(var i=0;i<orders.length;i++){if(orders[i].id===oid){idx=i;break;}}if(idx===-1)return;if(orders[idx].status!=='Pending'){showToast("Cannot cancel","error");return;}orders[idx].status='Cancelled';saveAllShopOrders(orders);fetch(FIREBASE_BASE_URL+'/xdrg_shop/orders/'+oid+'/status.json',{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify('Cancelled')}).catch(function(){});renderXdrgShop();showToast('✅ Cancelled','success');}
function openCashOutPage(){document.getElementById('pageTitle').innerText='💰 Money Rewards & Cash Out';renderCashOutPage();}
function selectCashAmount(a){saveCashOutFormState();selectedCashOutAmount=a;renderCashOutPage();}
function selectPaymentMethod(m){saveCashOutFormState();selectedPaymentMethod=m;renderCashOutPage();}
function saveCashOutFormState(){var n=document.getElementById('cashOutName');var num=document.getElementById('cashOutNumber');if(n)lastCashOutFormState.name=n.value;if(num)lastCashOutFormState.num=num.value;}
