  var currencySelectHtml='<div style="margin-bottom:15px;background:#eaf3ff;border:1px solid #a7d7f9;border-radius:6px;padding:12px"><label style="font-weight:bold;display:block;margin-bottom:6px;color:#005a9c">💱 Currency</label><select onchange="setLanguage(this.value)" style="width:100%;padding:10px;border:1px solid #a2a9b1;border-radius:4px;background:#fff;font-weight:bold;cursor:pointer">'+Object.keys(currencyLabels).map(function(k){return '<option value="'+k+'" '+(currentLanguage===k?'selected':'')+'>'+currencyLabels[k]+'</option>';}).join('')+'</select></div>';
